on conflict (ocp_accreditation) do update set
  name = excluded.name,
  address_line = excluded.address_line,
  city = excluded.city,
  postal_code = excluded.postal_code,
  phone = excluded.phone,
  fax = excluded.fax,
  status = excluded.status,
  ocp_status = excluded.ocp_status,
  source = excluded.source
where pharmacy_directory.claimed_by is null;

insert into pharmacy_directory
  (ocp_accreditation, name, address_line, city, province, postal_code,
