on conflict (ocp_accreditation) do update set
  name = excluded.name,
  address_line = excluded.address_line,
  city = excluded.city,
  postal_code = excluded.postal_code,
  phone = excluded.phone,
  fax = excluded.fax,
  status = excluded.status,
  ocp_status = excluded.ocp_status,
  source = excluded.source
where pharmacy_directory.claimed_by is null;

commit;

-- Verify
select ocp_status, status, count(*) from pharmacy_directory
  group by ocp_status, status order by 3 desc;
select count(*) as total, count(distinct city) as cities,
       count(*) filter (where status='listed') as bookable
  from pharmacy_directory;
